```cpp
#include "3mm.h"

extern "C" {
void kernel_3mm(
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmemE max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmemA max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmemB max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmemF max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmemC max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmemD max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmemG max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

  const int ni = NI;
  const int nj = NJ;
  const int nk = NK;
  const int nl = NL;
  const int nm = NM;

  int i, j, k;

  // Local staging buffers (on-chip)
  static double A_l[NI][NK];
  static double B_l[NK][NJ];
  static double C_l[NJ][NM];
  static double D_l[NM][NL];
  static double E_l[NI][NJ];
  static double F_l[NJ][NL];
  static double G_l[NI][NL];

  // The compute loops read 8 consecutive contraction-dim elements per lane
  // group.  To feed all 8 lanes AND all the k-steps without BRAM port
  // conflicts we COMPLETELY partition the contraction dimension of every
  // operand.  This gives every element of that dimension its own register/bank
  // so the fully-unrolled inner-k loop can perform all reads in one cycle.
  // A_l / E_l : contraction dim is dim=2  -> complete partition dim=2
  // B_l / F_l / D_l : contraction dim is dim=1 -> complete partition dim=1
  // C_l : contraction dim (nm) is dim=2 -> complete partition dim=2
#pragma HLS ARRAY_PARTITION variable=A_l complete dim=2
#pragma HLS ARRAY_PARTITION variable=B_l complete dim=1
#pragma HLS ARRAY_PARTITION variable=C_l complete dim=2
#pragma HLS ARRAY_PARTITION variable=D_l complete dim=1
#pragma HLS ARRAY_PARTITION variable=E_l complete dim=2
#pragma HLS ARRAY_PARTITION variable=F_l complete dim=1

  // ---- Load inputs from global memory into local buffers (contiguous bursts) ----
  for (i = 0; i < ni; i++)
    for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      A_l[i][k] = A[i][k];
    }

  for (k = 0; k < nk; k++)
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      B_l[k][j] = B[k][j];
    }

  for (i = 0; i < nj; i++)
    for (k = 0; k < nm; k++) {
#pragma HLS PIPELINE II=1
      C_l[i][k] = C[i][k];
    }

  for (k = 0; k < nm; k++)
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      D_l[k][j] = D[k][j];
    }

  // ---- E := A * B (compute from local memory) ----
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=E_l inter false
	double partial[8];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1
	for (int l = 0; l < 8; ++l) {
#pragma HLS UNROLL
	  partial[l] = 0.0;
	}
	for (k = 0; k < nk; k += 8) {
#pragma HLS UNROLL
	  for (int l = 0; l < 8; ++l) {
#pragma HLS UNROLL
	    int kk = k + l;
	    if (kk < nk)
	      partial[l] += A_l[i][kk] * B_l[kk][j];
	  }
	}
	E_l[i][j] = ((partial[0] + partial[1]) + (partial[2] + partial[3]))
	          + ((partial[4] + partial[5]) + (partial[6] + partial[7]));
      }

  // ---- F := C * D ----
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=F_l inter false
	double partial[8];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1
	for (int l = 0; l < 8; ++l) {
#pragma HLS UNROLL
	  partial[l] = 0.0;
	}
	for (k = 0; k < nm; k += 8) {
#pragma HLS UNROLL
	  for (int l = 0; l < 8; ++l) {
#pragma HLS UNROLL
	    int kk = k + l;
	    if (kk < nm)
	      partial[l] += C_l[i][kk] * D_l[kk][j];
	  }
	}
	F_l[i][j] = ((partial[0] + partial[1]) + (partial[2] + partial[3]))
	          + ((partial[4] + partial[5]) + (partial[6] + partial[7]));
      }

  // ---- G := E * F ----
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=G_l inter false
	double partial[8];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1
	for (int l = 0; l < 8; ++l) {
#pragma HLS UNROLL
	  partial[l] = 0.0;
	}
	for (k = 0; k < nj; k += 8) {
#pragma HLS UNROLL
	  for (int l = 0; l < 8; ++l) {
#pragma HLS UNROLL
	    int kk = k + l;
	    if (kk < nj)
	      partial[l] += E_l[i][kk] * F_l[kk][j];
	  }
	}
	G_l[i][j] = ((partial[0] + partial[1]) + (partial[2] + partial[3]))
	          + ((partial[4] + partial[5]) + (partial[6] + partial[7]));
      }

  // ---- Store results back to global memory (contiguous bursts) ----
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      E[i][j] = E_l[i][j];
    }

  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      F[i][j] = F_l[i][j];
    }

  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      G[i][j] = G_l[i][j];
    }

}
}
