```cpp
#include "3mm.h"

extern "C" {
void kernel_3mm(
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

  int i, j, k;

  // Local on-chip copies of all matrices (burst-friendly single-pass loads).
  static double A_loc[NI][NK];
  static double B_loc[NK][NJ];
  static double C_loc[NJ][NM];
  static double D_loc[NM][NL];
  static double E_loc[NI][NJ];
  static double F_loc[NJ][NL];
  static double G_loc[NI][NL];

  // Partition the reduction (k) dimension of each operand so both multiply
  // inputs are available in the same cycle inside the pipelined inner loop.
  // Cyclic partitioning gives multiple read ports without complete blow-up.
#pragma HLS ARRAY_PARTITION variable=A_loc cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=B_loc cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=C_loc cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=D_loc cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=E_loc cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=F_loc cyclic factor=8 dim=1

  // ---- Load inputs ----
  for (i = 0; i < ni; i++)
    for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      A_loc[i][k] = A[i][k];
    }

  for (k = 0; k < nk; k++)
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      B_loc[k][j] = B[k][j];
    }

  for (i = 0; i < nj; i++)
    for (k = 0; k < nm; k++) {
#pragma HLS PIPELINE II=1
      C_loc[i][k] = C[i][k];
    }

  for (k = 0; k < nm; k++)
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      D_loc[k][j] = D[k][j];
    }

  // ---- E = A * B ----
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
	double acc = 0.0;
	for (k = 0; k < nk; ++k) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=E_loc inter false
	  acc += A_loc[i][k] * B_loc[k][j];
	}
	E_loc[i][j] = acc;
      }

  // ---- F = C * D ----
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      {
	double acc = 0.0;
	for (k = 0; k < nm; ++k) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=F_loc inter false
	  acc += C_loc[i][k] * D_loc[k][j];
	}
	F_loc[i][j] = acc;
      }

  // ---- G = E * F ----
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
	double acc = 0.0;
	for (k = 0; k < nj; ++k) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=G_loc inter false
	  acc += E_loc[i][k] * F_loc[k][j];
	}
	G_loc[i][j] = acc;
      }

  // ---- Store outputs ----
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      E[i][j] = E_loc[i][j];
    }

  for (i = 0; i < nj; i++)
