        compute: for (int j = 0; j < M; j++) {
            #pragma HLS PIPELINE II=1
            #pragma HLS LOOP_TRIPCOUNT min=116 max=116
            #pragma HLS DEPENDENCE variable=local_s inter false
            #pragma HLS DEPENDENCE variable=local_A inter false
            #pragma HLS DEPENDENCE variable=local_p inter false
            double aij = local_A[j];
            local_s[j] = local_s[j] + ri * aij;
            qi = qi + aij * local_p[j];
