#pragma HLS INTERFACE m_axi port=s offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=q offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=p offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=s bundle=control
#pragma HLS INTERFACE s_axilite port=q bundle=control
#pragma HLS INTERFACE s_axilite port=p bundle=control
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

    int i, j;

    // ---- Local staging buffers (tile the full working set on-chip) ----
    double s_local[M];
    double p_local[M];
    double q_local[N];
    double r_local[N];
    double A_row[M];

    // ---------------- LOAD PHASE ----------------
    // Stage contiguous inputs into local buffers with pipelined bursts.
    load_p: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        p_local[j] = p[j];
    }

    load_r: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        r_local[i] = r[i];
    }

    // Initialize s locally (original: s[j]=0 for all m)
    init_s: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        s_local[j] = 0;
    }

    // ---------------- COMPUTE PHASE ----------------
    // Operates entirely on local buffers.
    //
    // s[j] = sum_i r[i] * A[i][j]  -> loop-carried across i on s_local[j].
    //        We keep j as the INNER pipelined dimension so consecutive
    //        pipeline iterations write DISTINCT s_local[j] elements.
    // q[i] = sum_j A[i][j] * p[j]  -> a clean reduction over j.
    outer_i: for (i = 0; i < n; i++) {
