        // The RMW hazard on s_local[j] is across i (outer), not across j,
        // so this inner loop has no true carried dependence and pipelines.
        update_s: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            s_local[j] = s_local[j] + ri * A_row[j];
