// Load one column j of data_l into a local column buffer (ping-pong target).
static void load_col(double data_l[N][M], double colbuf[N], int j, bool en)
{
  if (!en) return;
 load_col_i:
  for (int i = 0; i < N; i++)
    {
#pragma HLS PIPELINE II=1
      colbuf[i] = data_l[i][j];
    }
}

// Compute mean of a staged column buffer using partial-sum reduction.
static void compute_mean(double colbuf[N], double *out, double float_n, bool en)
{
  if (!en) return;
  const int UF = 4;
  const int DEPTH = 8;
  double partial[UF][DEPTH];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1
#pragma HLS ARRAY_PARTITION variable=partial complete dim=2
 cm_init_lane:
  for (int lane = 0; lane < UF; lane++)
    {
#pragma HLS UNROLL
     cm_init_depth:
      for (int d = 0; d < DEPTH; d++)
        {
#pragma HLS UNROLL
          partial[lane][d] = 0.0;
        }
    }
 cm_i:
  for (int i = 0; i < N; i += UF)
    {
#pragma HLS PIPELINE II=1
      int d = (i / UF) % DEPTH;
     cm_lane:
      for (int lane = 0; lane < UF; lane++)
        {
#pragma HLS UNROLL
          partial[lane][d] += colbuf[i + lane];
        }
    }
  double acc = 0.0;
 cm_comb_lane:
  for (int lane = 0; lane < UF; lane++)
    {
#pragma HLS UNROLL
     cm_comb_depth:
      for (int d = 0; d < DEPTH; d++)
        {
#pragma HLS UNROLL
          acc += partial[lane][d];
        }
    }
  *out = acc / float_n;
}

