{
#pragma HLS INTERFACE m_axi port=data offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=cov offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=mean offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data bundle=control
#pragma HLS INTERFACE s_axilite port=cov bundle=control
#pragma HLS INTERFACE s_axilite port=mean bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  const int UF = 4;
  const int DEPTH = 8;

  static double data_l[N][M];
  static double cov_l[M][M];
  static double mean_l[M];
#pragma HLS ARRAY_PARTITION variable=data_l cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=data_l cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=cov_l cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=mean_l cyclic factor=8 dim=1

  // Load input data into local buffer (contiguous, burst-friendly).
 load_data_i:
  for (i = 0; i < n; i++)
   load_data_j:
    for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE II=1
        data_l[i][j] = data[i][j];
      }

  // ---------------- Double-buffered mean computation -----------------
  // Ping-pong column buffers: load column j+1 while computing mean of j.
  static double colbuf0[N];
  static double colbuf1[N];
#pragma HLS ARRAY_PARTITION variable=colbuf0 cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=colbuf1 cyclic factor=4 dim=1

 mean_db:
  for (int t = 0; t < m + 1; t++)
    {
      bool load_en = (t < m);
      bool comp_en = (t > 0);
      int load_j = t;
      int comp_j = t - 1;

      if ((t & 1) == 0)
        {
          // even t: load into buf0, compute from buf1
          load_col(data_l, colbuf0, load_j, load_en);
          compute_mean(colbuf1, &mean_l[comp_j >= 0 ? comp_j : 0], float_n, comp_en);
        }
      else
        {
          // odd t: load into buf1, compute from buf0
          load_col(data_l, colbuf1, load_j, load_en);
          compute_mean(colbuf0, &mean_l[comp_j >= 0 ? comp_j : 0], float_n, comp_en);
        }
    }

  // Center data.
 center_i:
  for (i = 0; i < n; i++)
   center_j:
    for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE II=1
        data_l[i][j] -= mean_l[j];
      }

  // Compute covariance using DEPTH partial accumulators per lane over k.
 cov_i:
  for (i = 0; i < m; i++)
   cov_j:
    for (j = i; j < m; j++)
      {
        double cpartial[UF][DEPTH];
#pragma HLS ARRAY_PARTITION variable=cpartial complete dim=1
#pragma HLS ARRAY_PARTITION variable=cpartial complete dim=2
       cov_init_lane:
        for (int lane = 0; lane < UF; lane++)
          {
#pragma HLS UNROLL
           cov_init_depth:
            for (int d = 0; d < DEPTH; d++)
              {
#pragma HLS UNROLL
                cpartial[lane][d] = 0.0;
              }
          }

       cov_k:
        for (k = 0; k < n; k += UF)
          {
#pragma HLS PIPELINE II=1
            int cd = (k / UF) % DEPTH;
           cov_lane:
            for (int lane = 0; lane < UF; lane++)
              {
#pragma HLS UNROLL
                cpartial[lane][cd] +=
                    data_l[k + lane][i] * data_l[k + lane][j];
              }
          }

        double acc = 0.0;
       cov_combine_lane:
        for (int lane = 0; lane < UF; lane++)
          {
#pragma HLS UNROLL
           cov_combine_depth:
            for (int d = 0; d < DEPTH; d++)
              {
#pragma HLS UNROLL
                acc += cpartial[lane][d];
              }
          }
        double v = acc / (float_n - 1.0);
        cov_l[i][j] = v;
        cov_l[j][i] = v;
      }

  // Store results back to global memory (contiguous, burst-friendly).
 store_mean:
  for (j = 0; j < m; j++)
    {
#pragma HLS PIPELINE II=1
      mean[j] = mean_l[j];
    }

 store_cov_i:
  for (i = 0; i < m; i++)
   store_cov_j:
    for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE II=1
        cov[i][j] = cov_l[i][j];
      }

  // Also write back centered data to match original in-place semantics.
 store_data_i:
  for (i = 0; i < n; i++)
   store_data_j:
    for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE II=1
        data[i][j] = data_l[i][j];
      }

}
}
