#include "doitgen.h"
#include <string.h>

extern "C" {

void kernel_doitgen(
        double A[NR + 0][NQ + 0][NP + 0],
        double C4[NP + 0][NP + 0],
        double sum[NP + 0])
{
    #pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0 \
        max_read_burst_length=64 max_write_burst_length=64 \
        num_read_outstanding=16 num_write_outstanding=16 \
        max_widen_bitwidth=512
    #pragma HLS INTERFACE m_axi port=C4  offset=slave bundle=gmem1 \
        max_read_burst_length=64 max_write_burst_length=64 \
        num_read_outstanding=16 num_write_outstanding=16 \
        max_widen_bitwidth=512
    #pragma HLS INTERFACE m_axi port=sum offset=slave bundle=gmem2 \
        max_read_burst_length=64 max_write_burst_length=64 \
        num_read_outstanding=16 num_write_outstanding=16 \
        max_widen_bitwidth=512
    #pragma HLS INTERFACE s_axilite port=A      bundle=control
    #pragma HLS INTERFACE s_axilite port=C4     bundle=control
    #pragma HLS INTERFACE s_axilite port=sum    bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    // Double buffers for A rows (ping-pong)
    double row_buf_0[NP];
    double row_buf_1[NP];
    #pragma HLS ARRAY_PARTITION variable=row_buf_0 complete dim=1
    #pragma HLS ARRAY_PARTITION variable=row_buf_1 complete dim=1

    // Computed result buffers (ping-pong, separate from row_buf to avoid R/W conflict)
    double res_buf_0[NP];
    double res_buf_1[NP];
    #pragma HLS ARRAY_PARTITION variable=res_buf_0 complete dim=1
    #pragma HLS ARRAY_PARTITION variable=res_buf_1 complete dim=1

    // Local buffer for C4 (loaded once)
    double l_C4[NP][NP];
    #pragma HLS ARRAY_PARTITION variable=l_C4 cyclic factor=8 dim=2

    // Load C4 once
    for (int i = 0; i < NP; i++) {
        #pragma HLS PIPELINE II=1
        for (int j = 0; j < NP; j++) {
            #pragma HLS UNROLL factor=8
            l_C4[i][j] = C4[i][j];
        }
    }

    // Total number of (r,q) rows
    const int TOTAL = NR * NQ;  // = 500

    // Schedule with separate read/compute/write buffers:
    // row_buf_{k%2}  : holds the raw loaded row for iteration k
    // res_buf_{k%2}  : holds the computed result for iteration k
    //
    // Prologue/epilogue pattern (N = TOTAL):
    //   iter 0       : load row[0]->row_buf_0 ; compute(skip)               ; store(skip)
    //   iter 1       : load row[1]->row_buf_1 ; compute row[0] from row_buf_0->res_buf_0 ; store(skip)
    //   iter k(2..N-1): load row[k]->row_buf_{k%2} ; compute row[k-1] from row_buf_{(k-1)%2}->res_buf_{(k-1)%2} ; store row[k-2] from res_buf_{(k-2)%2}
    //   iter N       : load(skip) ; compute row[N-1] from row_buf_{(N-1)%2}->res_buf_{(N-1)%2} ; store row[N-2] from res_buf_{(N-2)%2}
    //   iter N+1     : load(skip) ; compute(skip) ; store row[N-1] from res_buf_{(N-1)%2}

    for (int iter = 0; iter < TOTAL + 2; iter++) {
        #pragma HLS loop_tripcount min=502 avg=502 max=502

        int load_idx  = iter;
        int comp_idx  = iter - 1;
        int store_idx = iter - 2;

        // --- STORE PHASE (goes first to avoid buffer conflict with LOAD) ---
        if (store_idx >= 0 && store_idx < TOTAL) {
            int r = store_idx / NQ;
            int q = store_idx % NQ;
            int sbuf = store_idx % 2;
            double* res_src = (sbuf == 0) ? res_buf_0 : res_buf_1;
            for (int p = 0; p < NP; p++) {
                #pragma HLS PIPELINE II=1
                A[r][q][p] = res_src[p];
            }
        }

        // --- LOAD PHASE ---
        if (load_idx >= 0 && load_idx < TOTAL) {
            int r = load_idx / NQ;
            int q = load_idx % NQ;
            int lbuf = load_idx % 2;
            double* row_dst = (lbuf == 0) ? row_buf_0 : row_buf_1;
            for (int p = 0; p < NP; p++) {
                #pragma HLS PIPELINE II=1
                row_dst[p] = A[r][q][p];
            }
        }

        // --- COMPUTE PHASE ---
        if (comp_idx >= 0 && comp_idx < TOTAL) {
            int cbuf = comp_idx % 2;
            double* row_src = (cbuf == 0) ? row_buf_0 : row_buf_1;
            double* res_dst = (cbuf == 0) ? res_buf_0 : res_buf_1;

            for (int p = 0; p < NP; p++) {
                #pragma HLS PIPELINE II=1
                double s = 0.0;
                for (int ss = 0; ss < NP; ss++) {
                    #pragma HLS UNROLL factor=8
                    s += row_src[ss] * l_C4[ss][p];
                }
                res_dst[p] = s;
            }
        }
    }

    // Write sum: the last computed row is row[TOTAL-1], result in res_buf_{(TOTAL-1)%2}
    {
        int last_buf = (TOTAL - 1) % 2;
        double* lsum = (last_buf == 0) ? res_buf_0 : res_buf_1;
        for (int p = 0; p < NP; p++) {
            #pragma HLS PIPELINE II=1
            sum[p] = lsum[p];
        }
    }
}

} // extern "C"
