    // Local buffers for staged computation - avoids AXI port conflicts
    double r_local[N];
    double y_local[N];
    double z[N];
    #pragma HLS ARRAY_PARTITION variable=r_local cyclic factor=4 dim=1
    #pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=4 dim=1
    #pragma HLS ARRAY_PARTITION variable=z      cyclic factor=4 dim=1

    double alpha;
    double beta;
    double sum;

    // Burst load r into local buffer
    load_r: for (int i = 0; i < n; i++) {
        #pragma HLS PIPELINE II=1
        r_local[i] = r[i];
    }

    // Initialize y_local
    y_local[0] = -r_local[0];
    beta  =  1.0;
    alpha = -r_local[0];

    for (int k = 1; k < n; k++) {
        beta = (1.0 - alpha * alpha) * beta;

        // Compute sum using local arrays with partial sum unrolling
        // Use 4 accumulators to break the loop-carried dependency chain
        double sum0 = 0.0, sum1 = 0.0, sum2 = 0.0, sum3 = 0.0;
        sum_loop: for (int i = 0; i < k; i += 4) {
            #pragma HLS PIPELINE II=1
            #pragma HLS DEPENDENCE variable=y_local inter false
            #pragma HLS DEPENDENCE variable=r_local inter false
            if (i + 0 < k) sum0 += r_local[k - (i+0) - 1] * y_local[i+0];
            if (i + 1 < k) sum1 += r_local[k - (i+1) - 1] * y_local[i+1];
            if (i + 2 < k) sum2 += r_local[k - (i+2) - 1] * y_local[i+2];
            if (i + 3 < k) sum3 += r_local[k - (i+3) - 1] * y_local[i+3];
