        // Copy z back to y_local
        copy_loop: for (int i = 0; i < k; i++) {
            #pragma HLS PIPELINE II=1
            #pragma HLS UNROLL factor=4
            y_local[i] = z[i];
        }
        y_local[k] = alpha;
    }

