    const int n = N;

    // Local staging buffers (narrow ABI preserved)
    double r_local[N];
    double y_local[N];
    double z[N];
#pragma HLS ARRAY_PARTITION variable=r_local cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=z      cyclic factor=4 dim=1

    double alpha;
    double beta;
    double sum;

    int i, k;

    // ---- Contiguous burst load of r into local buffer ----
    load_r: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        r_local[i] = r[i];
    }

    y_local[0] = -r_local[0];
    beta = 1.0;
    alpha = -r_local[0];

    const int LANES = 4;
    const int ACC_DEPTH = 8; // >= FP add latency to break the recurrence

    // ---- Double-buffered (ping-pong) partial-sum accumulators ----
    // Two independent sets of partial accumulators, selected by outer-loop
    // parity (k & 1). Each outer iteration writes ONLY its own set, so no
    // FP-add recurrence is carried across k boundaries and the reduction can
    // be scheduled at II=1. Arithmetic (lane/acc mapping and final summation
    // order) is byte-identical to the single-buffer version because each set
    // is fully re-initialized to 0.0 before use.
    double partial_A[LANES][ACC_DEPTH];
    double partial_B[LANES][ACC_DEPTH];
#pragma HLS ARRAY_PARTITION variable=partial_A complete dim=1
#pragma HLS ARRAY_PARTITION variable=partial_A complete dim=2
#pragma HLS ARRAY_PARTITION variable=partial_B complete dim=1
#pragma HLS ARRAY_PARTITION variable=partial_B complete dim=2

    for (k = 1; k < n; k++) {
#pragma HLS loop_tripcount min=1 avg=60 max=119
        beta = (1 - alpha * alpha) * beta;

        // Select active accumulator set for this outer iteration.
        const int buf_flag = k & 1;

        // ---- Initialize the ACTIVE partial set (ping-pong) ----
        init_partial: for (int lane = 0; lane < LANES; lane++) {
#pragma HLS UNROLL
            for (int d = 0; d < ACC_DEPTH; d++) {
#pragma HLS UNROLL
                if (buf_flag) {
                    partial_B[lane][d] = 0.0;
                } else {
                    partial_A[lane][d] = 0.0;
                }
            }
        }

        // ---- Reduction over the ACTIVE partial set ----
        int step = 0;
        sum_loop: for (i = 0; i < k; i += LANES) {
#pragma HLS PIPELINE II=1
#pragma HLS loop_tripcount min=1 avg=15 max=30
            int acc = step & (ACC_DEPTH - 1);
            sum_lane: for (int lane = 0; lane < LANES; lane++) {
#pragma HLS UNROLL
