        double lane_sum[LANES];
#pragma HLS ARRAY_PARTITION variable=lane_sum complete dim=1
        combine_acc: for (int lane = 0; lane < LANES; lane++) {
#pragma HLS UNROLL
            double s = 0.0;
            for (int d = 0; d < ACC_DEPTH; d++) {
#pragma HLS UNROLL
