extern "C" {
void kernel_floyd_warshall(
			   int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

  const int n = N;

  int i, j, k;

  // Full matrix staged on-chip (tiling: whole matrix as one tile).
  static int local_path[N][N];
#pragma HLS ARRAY_PARTITION variable=local_path cyclic factor=4 dim=2

  // Row-k buffer: staged once per k, reused across all i iterations.
  // Fully partitioned so every element can be read in parallel by the
  // pipelined inner loop without a port conflict.
  static int akj_row[N];
#pragma HLS ARRAY_PARTITION variable=akj_row cyclic factor=4 dim=1

  // ---------------- LOAD phase ----------------
  // Burst-friendly contiguous load of the full matrix into on-chip buffer.
  load_i: for (i = 0; i < n; i++)
    load_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      local_path[i][j] = path[i][j];
    }

  // ---------------- COMPUTE phase ----------------
  // Floyd-Warshall on the on-chip tile.
  for (k = 0; k < n; k++)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N

      // Stage row k into a local reuse buffer.  This row is read N times
      // (once per i), so staging it here avoids repeated 2-D reads and
      // gives the inner loop conflict-free access to akj values.
      stage_k: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        akj_row[j] = local_path[k][j];
      }

      compute_i: for (i = 0; i < n; i++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
	int aik = local_path[i][k];      // loop-invariant across j
	compute_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=local_path inter false
	  int akj  = akj_row[j];
	  int cur  = local_path[i][j];
	  int cand = aik + akj;
	  local_path[i][j] = cur < cand ? cur : cand;
	}
      }
    }

  // ---------------- STORE phase ----------------
  // Burst-friendly contiguous store back to global memory.
  store_i: for (i = 0; i < n; i++)
    store_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      path[i][j] = local_path[i][j];
