#include "floyd-warshall.h"

extern "C" {

void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  // Stage the entire path matrix into local memory to enable reuse and
  // low-latency pipelined access. N=180 -> 180x180 ints fits in on-chip RAM.
  static int local_path[N][N];
  // Cyclic on dim=2 (the j dimension) so the unrolled inner j-lanes each
  // get an independent memory bank. Factor kept modest to relieve timing.
  #pragma HLS ARRAY_PARTITION variable=local_path cyclic factor=4 dim=2

  // Load from global memory into local buffer.
  load_i: for (i = 0; i < n; i++) {
    load_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      local_path[i][j] = path[i][j];
    }
  }

  // Main Floyd-Warshall computation on local memory.
  //
  // The k loop carries a TRUE recurrence: iteration k uses row/column values
  // (local_path[i][k], local_path[k][j]) that may have been updated in earlier
  // k iterations. Therefore k must remain sequential (do NOT pipeline across k).
  //
  // For a FIXED (k, i): local_path[i][k] and local_path[k][j] are read-only
  // within this iteration, and each write local_path[i][j] targets a distinct
  // column j. Thus the j loop iterations are independent -> pipeline & unroll j.
  k_loop: for (k = 0; k < n; k++)
    {
      i_loop: for (i = 0; i < n; i++)
	{
	  // Hoist the (i,k) value once; it is loop-invariant over j.
	  const int pik = local_path[i][k];
	  j_loop: for (j = 0; j < n; j++)
	    {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
	      const int via_k = pik + local_path[k][j];
	      const int cur   = local_path[i][j];
	      local_path[i][j] = cur < via_k ? cur : via_k;
	    }
	}
    }

  // Store results back to global memory.
  store_i: for (i = 0; i < n; i++) {
    store_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      path[i][j] = local_path[i][j];
    }
  }

}

