extern "C" {
void kernel_jacobi_1d(

			    double A[ N + 0],
			    double B[ N + 0])
{
// Separate bundles so A and B are on independent AXI buses.  This lets the
// two load (and two store) processes run concurrently under DATAFLOW without
// violating the "one reader / one writer per bundle" rule.
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmemA max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmemB max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int tsteps = TSTEPS;

    int t, i;

    // Local staging buffers.
    double A_local[N];
    double B_local[N];
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=8 dim=1

    // ---- Double-buffered load phase ----
    // Overlap the load of A into A_local with the load of B into B_local
    // using a 2-iteration ping-pong schedule (DATAFLOW).
    // iter 0: load A  (flag on) ; load B skipped
    // iter 1: load B  (flag on) ; load A skipped
    // A and B are on independent bundles, so DATAFLOW overlaps them legally.
    load_phase: for (int p = 0; p < 2; p++) {
#pragma HLS DATAFLOW
        load(A, A_local, (p == 0));
        load(B, B_local, (p == 1));
    }

    // ---- Compute (unchanged: alternates between the two buffers) ----
    time_loop: for (t = 0; t < tsteps; t++)
    {
#pragma HLS LOOP_TRIPCOUNT min=TSTEPS max=TSTEPS
        comp1: for (i = 1; i < n - 1; i++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=B_local inter false
            B_local[i] = 0.33333 * (A_local[i-1] + A_local[i] + A_local[i + 1]);
        }
        comp2: for (i = 1; i < n - 1; i++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=A_local inter false
            A_local[i] = 0.33333 * (B_local[i-1] + B_local[i] + B_local[i + 1]);
        }
    }

    // ---- Double-buffered store phase ----
    // Overlap the store of A_local -> A with B_local -> B.
    // iter 0: store A (flag on) ; store B skipped
    // iter 1: store B (flag on) ; store A skipped
    store_phase: for (int p = 0; p < 2; p++) {
#pragma HLS DATAFLOW
        store(A, A_local, (p == 0));
        store(B, B_local, (p == 1));
    }

