            w = A[i][j];
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w;
        }
    }

    // Forward substitution
    for (i = 0; i < n; i++) {
        w = b[i];
        for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
            w -= A[i][j] * y[j];
        }
        y[i] = w;
    }

    // Backward substitution
    for (i = n - 1; i >= 0; i--) {
        w = y[i];
        for (j = i + 1; j < n; j++) {
#pragma HLS PIPELINE II=1
