void kernel_trisolv(
		    double L[ N + 0][N + 0],
		    double x[ N + 0],
		    double b[ N + 0])
{
#pragma HLS INTERFACE m_axi port=L offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem max_read_burst_length=64 max_write_burst_length=64 num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=L bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    int i, j;

    // Local buffers for tiled/coalesced burst transfers
    double b_local[N];
    double x_local[N];

    // ---- DOUBLE BUFFERING: two copies of the per-row L buffer ----
    double L_row_1[N];
    double L_row_2[N];
    double Lii_1, Lii_2;
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=L_row_1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=L_row_2 cyclic factor=8 dim=1

    // ---- LOAD phase: contiguous burst load of b into local buffer ----
    for (i = 0; i < n; i++)
    {
#pragma HLS PIPELINE II=1
        b_local[i] = b[i];
    }

    const int UF = 8;

    // ============================================================
    // Double-buffered main loop.
    // We prefetch L_row for row (i+1) while computing row i.
    // Load and compute are independent (L is read-only), so the
    // overlap does not change any computed value: the compute
    // schedule and its inputs/outputs are byte-identical to the
    // single-buffer version.
    //
    // Prologue: load row 0 before the loop.
    // Loop iteration 't' (t = 0 .. n-1):
    //   - flag = t % 2 selects the buffer set holding row t (loaded
    //     in the previous iteration or prologue)
    //   - compute row t from buffer set 'flag'
    //   - if (t+1 < n) load row (t+1) into buffer set '!flag'
    // ============================================================

    // ---- PROLOGUE: load row 0 into buffer set 0 (L_row_1) ----
    for (j = 0; j < 0; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=0 max=120
#pragma HLS PIPELINE II=1
        L_row_1[j] = L[0][j];
    }
    Lii_1 = L[0][0];

    for (i = 0; i < n; i++)
    {
        int flag = i & 1; // 0 -> use set 1, 1 -> use set 2

        // ---- LOAD next row (i+1) into the OTHER buffer set ----
        int inext = i + 1;
        if (inext < n)
        {
            if (flag == 0)
            {
                // current compute uses set 1, prefetch into set 2
                for (j = 0; j < inext; j++)
                {
#pragma HLS LOOP_TRIPCOUNT min=0 max=120
#pragma HLS PIPELINE II=1
                    L_row_2[j] = L[inext][j];
                }
                Lii_2 = L[inext][inext];
            }
            else
            {
                // current compute uses set 2, prefetch into set 1
                for (j = 0; j < inext; j++)
                {
#pragma HLS LOOP_TRIPCOUNT min=0 max=120
#pragma HLS PIPELINE II=1
                    L_row_1[j] = L[inext][j];
                }
                Lii_1 = L[inext][inext];
            }
