                {
#pragma HLS UNROLL
                    int jj = j + lane;
                    if (jj < i)
                        part[lane] += L_row_1[jj] * x_local[jj];
                }
            }

            double acc = b_local[i];
            for (int k = 0; k < UF; k++)
            {
#pragma HLS UNROLL
                acc -= part[k];
            }
            x_local[i] = acc / Lii_1;
        }
        else
