#include "trisolv.h"

void kernel_trisolv(
        double L[N + 0][N + 0],
        double x[N + 0],
        double b[N + 0])
{
#pragma HLS INTERFACE m_axi port=L offset=slave bundle=gmem \
    max_read_burst_length=64 max_write_burst_length=64 \
    num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem \
    max_read_burst_length=64 max_write_burst_length=64 \
    num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem \
    max_read_burst_length=64 max_write_burst_length=64 \
    num_read_outstanding=16 num_write_outstanding=16
#pragma HLS INTERFACE s_axilite port=L bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local buffer to stage x values (avoid repeated AXI reads)
    double x_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1

    // Double-buffered local buffers for rows of L
    double L_row_0[N];
#pragma HLS ARRAY_PARTITION variable=L_row_0 cyclic factor=8 dim=1
    double L_row_1[N];
#pragma HLS ARRAY_PARTITION variable=L_row_1 cyclic factor=8 dim=1

    // Load b into x_local as initial values
    load_b: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
        x_local[i] = b[i];
    }

    // Double-buffering prologue/epilogue pattern:
    // Outer loop runs N+1 iterations (iter 0..N)
    //   iter 0   : load row 0 into buf_0 ; compute(skip)         ; no store
    //   iter 1   : load row 1 into buf_1 ; compute row 0 from buf_0
    //   iter 2   : load row 2 into buf_0 ; compute row 1 from buf_1
    //   ...
    //   iter N   : load(skip)            ; compute row N-1 from buf_{N-1 % 2}

    // Prologue: load row 0 into L_row_0 before the main loop
    load_prologue: for (int j = 0; j <= 0; j++) {
#pragma HLS PIPELINE II=1
        L_row_0[j] = L[0][j];
    }

    // Main double-buffered loop: iterations 1..N
    // At iteration i (1-based): load row i (if i < n) into the "next" buffer,
    // compute using row (i-1) from the "current" buffer.
    double sum_saved = x_local[0]; // sum for row 0 before inner loop
    // We need to handle the sum initialization per row carefully.
    // Use a variable to carry the sum across the double-buffer boundary.

    // Restructure: run N+1 outer iterations
    // iter = 0: load buf for row 0 (already done in prologue)
    // iter = 1..N: load buf for row iter (if iter < n), compute row (iter-1)

    for (int iter = 1; iter <= n; iter++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N

        int compute_row = iter - 1;       // which row to compute
        int load_row    = iter;            // which row to load next
        int cur_buf     = compute_row % 2; // buffer holding compute_row data
        int nxt_buf     = load_row    % 2; // buffer to load load_row into

        // --- LOAD PHASE: load row 'load_row' into buffer 'nxt_buf' ---
        if (load_row < n) {
            if (nxt_buf == 0) {
                load_next_0: for (int j = 0; j <= load_row; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
                    L_row_0[j] = L[load_row][j];
                }
            } else {
                load_next_1: for (int j = 0; j <= load_row; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
                    L_row_1[j] = L[load_row][j];
                }
            }
        }

        // --- COMPUTE PHASE: compute row 'compute_row' using buffer 'cur_buf' ---
        double sum = x_local[compute_row]; // initialized to b[compute_row]

        if (cur_buf == 0) {
            inner_0: for (int j = 0; j < compute_row; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS DEPENDENCE variable=x_local inter false
#pragma HLS DEPENDENCE variable=L_row_0 inter false
                sum -= L_row_0[j] * x_local[j];
            }
            x_local[compute_row] = sum / L_row_0[compute_row];
        } else {
            inner_1: for (int j = 0; j < compute_row; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS DEPENDENCE variable=x_local inter false
#pragma HLS DEPENDENCE variable=L_row_1 inter false
                sum -= L_row_1[j] * x_local[j];
            }
            x_local[compute_row] = sum / L_row_1[compute_row];
        }
    }

    // Burst-write x_local back to x in one contiguous pass
    store_x: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=N max=N
        x[i] = x_local[i];
    }
}
