#include "trmm.h"
#include <string.h>

extern "C" {

// Tile size for B columns
#define TILE_N 16

static void load_B_tile(
    double B[M][N],
    double B_local[M][TILE_N],
    int tile_j)
{
    load_B_tile_loop:
    for (int i = 0; i < M; i++) {
        #pragma HLS LOOP_TRIPCOUNT min=M max=M
        for (int j = 0; j < TILE_N; j++) {
            #pragma HLS PIPELINE II=1
            #pragma HLS LOOP_TRIPCOUNT min=TILE_N max=TILE_N
            int gj = tile_j * TILE_N + j;
            B_local[i][j] = (gj < N) ? B[i][gj] : 0.0;
        }
    }
}

static void compute_tile(
    double alpha,
    double A_cols[M][M],
    double B_local[M][TILE_N])
{
    #pragma HLS ARRAY_PARTITION variable=A_cols cyclic factor=4 dim=2
    #pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=8 dim=2

    compute_rows:
    for (int i = 0; i < M; i++) {
        #pragma HLS LOOP_TRIPCOUNT min=M max=M

        // Accumulate contributions from rows k > i
        accumulate_k:
        for (int k = i + 1; k < M; k++) {
            #pragma HLS LOOP_TRIPCOUNT min=0 max=M
            accumulate_j:
            for (int j = 0; j < TILE_N; j++) {
                #pragma HLS PIPELINE II=1
                #pragma HLS LOOP_TRIPCOUNT min=TILE_N max=TILE_N
                #pragma HLS DEPENDENCE variable=B_local inter false
                B_local[i][j] += A_cols[i][k] * B_local[k][j];
            }
        }

        // Scale by alpha - unroll this independent loop
        scale_j:
        for (int j = 0; j < TILE_N; j++) {
            #pragma HLS UNROLL factor=8
            #pragma HLS LOOP_TRIPCOUNT min=TILE_N max=TILE_N
            B_local[i][j] = alpha * B_local[i][j];
        }
    }
}

static void store_B_tile(
    double B[M][N],
    double B_local[M][TILE_N],
    int tile_j)
{
    store_B_tile_loop:
    for (int i = 0; i < M; i++) {
        #pragma HLS LOOP_TRIPCOUNT min=M max=M
        for (int j = 0; j < TILE_N; j++) {
            #pragma HLS PIPELINE II=1
            #pragma HLS LOOP_TRIPCOUNT min=TILE_N max=TILE_N
            int gj = tile_j * TILE_N + j;
            if (gj < N) B[i][gj] = B_local[i][j];
        }
    }
}

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
    #pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem_a \
        max_widen_bitwidth=512 \
        max_read_burst_length=64 max_write_burst_length=64 \
        num_read_outstanding=16 num_write_outstanding=16
    #pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem_b \
        max_widen_bitwidth=512 \
        max_read_burst_length=64 max_write_burst_length=64 \
        num_read_outstanding=16 num_write_outstanding=16
    #pragma HLS INTERFACE s_axilite port=alpha bundle=control
    #pragma HLS INTERFACE s_axilite port=A bundle=control
    #pragma HLS INTERFACE s_axilite port=B bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffer: store all A columns needed for trmm
    double A_cols[M][M];
    #pragma HLS ARRAY_PARTITION variable=A_cols cyclic factor=4 dim=2

    // Local tile buffer for B
    double B_local[M][TILE_N];
    #pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=8 dim=2

    // === LOAD PHASE: Load all required A columns into local buffer ===
    load_A_all:
    for (int i = 0; i < M; i++) {
        #pragma HLS LOOP_TRIPCOUNT min=M max=M
        load_A_col_i:
        for (int k = 0; k < M; k++) {
            #pragma HLS PIPELINE II=1
            #pragma HLS LOOP_TRIPCOUNT min=M max=M
            A_cols[i][k] = A[k][i];
        }
    }

    // === TILE LOOP: Process B in tiles of TILE_N columns ===
    int num_tiles = (N + TILE_N - 1) / TILE_N;

    tile_loop:
    for (int t = 0; t < num_tiles; t++) {
        #pragma HLS LOOP_TRIPCOUNT min=N/TILE_N max=N/TILE_N+1

        // --- LOAD tile of B ---
        load_B_tile(B, B_local, t);

        // --- COMPUTE on local tile ---
        compute_tile(alpha, A_cols, B_local);

        // --- STORE tile back to B ---
        store_B_tile(B, B_local, t);
    }
}

} // extern "C"
